// SPLParserInit initializes any static state used to implement SPLParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewSPLParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func SPLParserInit() {
	staticData := &SPLParserParserStaticData
	staticData.once.Do(splparserParserInit)
}

// NewSPLParser produces a new parser instance for the optional input antlr.TokenStream.
func NewSPLParser(input antlr.TokenStream) *SPLParser {
	SPLParserInit()
	this := new(SPLParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &SPLParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "SPLParser.g4"

	return this
}

// Note that '@members' cannot be changed now, but this should have been 'globals'
// If you are looking to have variables for each instance, use '@structmembers'

func (p *SPLParser) analysisCommandIs(names ...string) bool {
	name := p.GetTokenStream().LT(1).GetText()
	for _, candidate := range names {
		if strings.EqualFold(name, candidate) {
			return true
		}
	}
	return false
}

// Whitespace/comments end unquoted search values even though their tokens are hidden.
func (p *SPLParser) analysisTokensAdjacent() bool {
	previous, next := p.GetTokenStream().LT(-1), p.GetTokenStream().LT(1)
	return previous != nil && next != nil && previous.GetStop()+1 == next.GetStart()
}
func (p *SPLParser) analysisIsCommand() bool {
	kind := p.GetTokenStream().LA(1)
	return kind == SPLParserINIT_COMMAND || kind == SPLParserSTD_COMMAND || kind == SPLParserSTD_COMMAND_AND_FUNCTION
}

